// Recebe o output de um node "Identificar: <cliente>" (que carimbou page_id/form_id/
// client_label em cima do payload original do Facebook Lead Ads Trigger — field_data,
// id (leadgen_id), created_time, ad_id, ad_name, campaign_name, etc) e monta o payload
// do contrato POST /api/leads/captura (LeadCaptureController), no mesmo formato do
// workflow "Insert Lead (Site)", só trocando source_channel/source_identifier e a
// extração de nome/e-mail/telefone — no Facebook isso vem em field_data: [{name, values}]
// em vez de campos soltos no payload.
//
// Contrato importante: source_channel FIXO 'facebook_lead_ad' (bate com
// LeadChannel.kind, já seedado por organização) e source_identifier no formato
// EXATO "page_id:form_id" — é o que precisa estar cadastrado em
// client_lead_sources.external_id (aba "Fontes de Lead" da ficha do cliente) pra o
// lead ser identificado (201). Sem match, o endpoint responde 202 e o lead cai em
// triagem manual mesmo assim — nunca é descartado.

const item = $input.first().json;

// field_data → mapa { chave: valor } (Meta usa chaves padronizadas pras perguntas
// "prontas" do formulário; perguntas customizadas vêm com a chave que o anunciante
// deu no form, então nome/email/telefone abaixo cobrem só as mais comuns).
const fieldMap = {};
for (const f of (item.field_data || [])) {
  fieldMap[f.name] = (f.values && f.values[0]) || null;
}

const name = fieldMap.full_name
  || [fieldMap.first_name, fieldMap.last_name].filter(Boolean).join(' ')
  || null;

return {
  json: {
    source_channel:    'facebook_lead_ad',
    source_identifier: `${item.page_id}:${item.form_id}`,
    name:              name || null,
    email:             fieldMap.email || null,
    phone:             fieldMap.phone_number || null,
    form_name:         item.client_label || null,
    landing_page_url:  null,
    utm_source:        'facebook',
    utm_medium:        'lead_ad',
    utm_campaign:      item.campaign_name || null,
    utm_content:       item.ad_name || null,
    utm_term:          null,
    city:              fieldMap.city || null,
    state:             fieldMap.state || null,
    event_id:          item.id || null,
    received_at:       item.created_time || new Date().toISOString(),
    raw_payload:       item,
  },
};
